$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$utf8=New-Object Text.UTF8Encoding($false,$true)
function Get-LowerHash([string]$Path){return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
function Get-StringHash([string]$Value){$sha=[Security.Cryptography.SHA256]::Create();try{return([BitConverter]::ToString($sha.ComputeHash($utf8.GetBytes($Value)))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}}
function Read-Json([string]$Path){return Get-Content -LiteralPath $Path -Raw -Encoding UTF8|ConvertFrom-Json}
function Convert-Json($Value,[int]$Depth=50){$json=($Value|ConvertTo-Json -Depth $Depth).Replace("`r`n","`n").Replace("`r","`n");if(-not$json.EndsWith("`n")){$json+="`n"};return $json}
function Write-AtomicJson([string]$Path,$Value,[int]$Depth=50){$parent=Split-Path -Parent $Path;if(-not(Test-Path -LiteralPath $parent -PathType Container)){New-Item -ItemType Directory -Path $parent|Out-Null};$tmp=$Path+'.tmp-'+[Guid]::NewGuid().ToString('N');[IO.File]::WriteAllText($tmp,(Convert-Json $Value $Depth),$utf8);if(Test-Path -LiteralPath $Path){$bak=$Path+'.replace-backup-'+[Guid]::NewGuid().ToString('N');[IO.File]::Replace($tmp,$Path,$bak);if(Test-Path -LiteralPath $bak){[IO.File]::Delete($bak)}}else{[IO.File]::Move($tmp,$Path)}}
function Write-CreateNewJson([string]$Path,$Value,[int]$Depth=50){if(Test-Path -LiteralPath $Path){throw "Create-new JSON exists: $Path"};$parent=Split-Path -Parent $Path;if(-not(Test-Path -LiteralPath $parent -PathType Container)){New-Item -ItemType Directory -Path $parent|Out-Null};$tmp=$Path+'.tmp-'+[Guid]::NewGuid().ToString('N');[IO.File]::WriteAllText($tmp,(Convert-Json $Value $Depth),$utf8);if(Test-Path -LiteralPath $Path){throw "Create-new JSON appeared concurrently: $Path"};[IO.File]::Move($tmp,$Path)}
function Is-Within([string]$Candidate,[string]$Root){$r=[IO.Path]::GetFullPath($Root).TrimEnd('\')+'\';return [IO.Path]::GetFullPath($Candidate).StartsWith($r,[StringComparison]::OrdinalIgnoreCase)}
function Get-LaneUnityProcesses([string]$ProjectPath){return @(Get-CimInstance Win32_Process -Filter "Name='Unity.exe'" -ErrorAction SilentlyContinue|Where-Object{[string]$_.CommandLine -like ('*'+$ProjectPath+'*')})}
function Read-LogText([string]$Path){try{if(Test-Path -LiteralPath $Path){return [IO.File]::ReadAllText($Path)}}catch{};return ''}

$SourceProjectPath=[IO.Path]::GetFullPath($SourceProjectPath);$LaneProjectPath=[IO.Path]::GetFullPath($LaneProjectPath);$UnityPath=[IO.Path]::GetFullPath($UnityPath)
$BlockPlanPath=[IO.Path]::GetFullPath($BlockPlanPath);$OutputDirectory=[IO.Path]::GetFullPath($OutputDirectory);$AllowedRoot=[IO.Path]::GetFullPath($AllowedRoot);$BarrierRoot=[IO.Path]::GetFullPath($BarrierRoot)
$expectedLane=[IO.Path]::GetFullPath(('H:\DDM_Final_Project_Gate13R48H\v1\lane-{0:D2}'-f$LaneNumber))
$expectedAllowed=if($Mode-eq'Pilot'){[IO.Path]::GetFullPath((Join-Path $SourceProjectPath 'Research\PilotRuns\Gate13R_48h_10pct_3Lane\v1'))}else{[IO.Path]::GetFullPath((Join-Path $SourceProjectPath 'Research\Verification\Gate13R_48h_10pct_3Lane\v1'))}
if($LaneProjectPath-ne$expectedLane){throw "Lane project path mismatch: expected $expectedLane"};if($AllowedRoot-ne$expectedAllowed){throw "Allowed root mismatch for mode $Mode."}
if(-not(Is-Within $OutputDirectory $AllowedRoot)-or-not(Is-Within $BlockPlanPath $AllowedRoot)-or-not(Is-Within $BarrierRoot $AllowedRoot)-or-not(Is-Within $OutputDirectory $BarrierRoot)){throw 'Plan/output/barrier root violates the authorized root boundary.'}
