if(-not(Test-Path -LiteralPath $BarrierRoot -PathType Container)){throw 'Barrier root must exist before wrapper launch.'}
if(-not(Test-Path -LiteralPath $LaneProjectPath -PathType Container)-or-not(Test-Path -LiteralPath (Join-Path $LaneProjectPath 'Assets') -PathType Container)){throw 'Lane project copy is missing.'}
if(-not(Test-Path -LiteralPath $UnityPath -PathType Leaf)){throw 'Unity executable is missing.'};if(-not(Test-Path -LiteralPath $BlockPlanPath -PathType Leaf)){throw 'Block plan is missing.'}
foreach($formal in @('Research\FormalRuns\Gate13R_ProcessReuse_5pct\v1','Research\FormalRuns\Gate13R_36h_10pct_4Lane\v1','Research\FormalRuns\Gate13R_48h_10pct_3Lane\v1')){if(Test-Path -LiteralPath (Join-Path $SourceProjectPath $formal)){throw "Forbidden formal root exists: $formal"}}
if(Test-Path -LiteralPath (Join-Path $LaneProjectPath 'Temp\UnityLockfile')){throw 'Lane Unity lock exists before block start.'};if(@(Get-LaneUnityProcesses $LaneProjectPath).Count){throw 'A Unity process already owns the lane project.'}
if(Test-Path -LiteralPath $OutputDirectory){if(-not(Test-Path -LiteralPath $OutputDirectory -PathType Container)-or@(Get-ChildItem -LiteralPath $OutputDirectory -Force).Count){throw "Output is not fresh: $OutputDirectory"}}

$unityLog=$OutputDirectory+'.Unity.log';$summaryPath=$OutputDirectory+'.wrapper-summary.json';$failureSidecar=$OutputDirectory+'.wrapper-failure.json';$admissionPath=$OutputDirectory+'.license-admission.json';$methodReadyPath=Join-Path $OutputDirectory 'method-ready.json';$releasePath=Join-Path $BarrierRoot 'barrier-release.json';$barrierObservedPath=Join-Path $OutputDirectory 'barrier-observed.json'
foreach($path in @($unityLog,$summaryPath,$failureSidecar,$admissionPath)){if(Test-Path -LiteralPath $path){throw "Create-new sidecar exists: $path"}}
$plan=Read-Json $BlockPlanPath;if([int]$plan.schemaVersion-ne2-or[string]$plan.designId-ne'gate13r-48h-10pct-three-isolated-editor-lanes-serial-license-admission-v1'-or$plan.formalCampaign-ne$false){throw 'Unauthorized block-plan identity/boundary.'}
$allowedRoles=if($Mode-eq'Pilot'){@('excluded-warmup','measured-non-formal-pilot')}else{@('excluded-verification','excluded-negative-fail-closed-verification')};if([string]$plan.analysisRole-notin$allowedRoles){throw "Analysis role is not allowed in $Mode mode."}
if($ExpectFailure-and[string]$plan.analysisRole-ne'excluded-negative-fail-closed-verification'){throw 'ExpectFailure requires the negative role.'};if(-not$ExpectFailure-and[string]$plan.analysisRole-eq'excluded-negative-fail-closed-verification'){throw 'Negative role requires ExpectFailure.'}
$expectedMasks=@('0x000000FF','0x0000FF00','0x00FF0000');if($AffinityMaskHex.ToUpperInvariant()-ne$expectedMasks[$LaneNumber-1]){throw 'Affinity mask differs from the frozen lane policy.'}

$maskValue=[Convert]::ToUInt64($AffinityMaskHex.Substring(2),16);$planSha=Get-LowerHash $BlockPlanPath;$started=[DateTimeOffset]::Now;$process=$null;$timedOut=$false;$exitCode=-1;$actualMask=$null;$licenseAdmitted=$false;$licenseAdmittedAt=$null;$errors=New-Object Collections.Generic.List[string]
try{
    $args=@('-batchmode','-nographics','-quit','-projectPath',('"'+$LaneProjectPath+'"'),'-executeMethod','DDM.Research.Editor.Gate13R48h3LaneBatchCommandV1.Run','-ddmGate10RBlockPlanPath',('"'+$BlockPlanPath+'"'),'-ddmGate10RBlockPlanSha256',$planSha,'-ddmGate10ROutputDirectory',('"'+$OutputDirectory+'"'),'-ddmGate13ROutputDirectory',('"'+$OutputDirectory+'"'),'-ddmGate13RBarrierRoot',('"'+$BarrierRoot+'"'),'-ddmGate13RMethodReadyPath',('"'+$methodReadyPath+'"'),'-ddmGate13RBarrierReleasePath',('"'+$releasePath+'"'),'-ddmGate13RWaveId',$WaveId,'-ddmGate13RBarrierToken',$BarrierToken,'-ddmGate13RBarrierTimeoutSeconds',[string]$BarrierTimeoutSeconds,'-logFile',('"'+$unityLog+'"'))
    $process=Start-Process -FilePath $UnityPath -ArgumentList $args -WorkingDirectory (Split-Path -Parent $UnityPath) -WindowStyle Hidden -PassThru
    $process.ProcessorAffinity=[IntPtr]([Int64]$maskValue);$process.PriorityClass=[Diagnostics.ProcessPriorityClass]::Normal;$process.Refresh();$actualMask=('0x{0:X8}'-f[uint64]$process.ProcessorAffinity.ToInt64())
    $admissionDeadline=(Get-Date).AddSeconds($LicenseAdmissionTimeoutSeconds)
    while(-not$licenseAdmitted){
        $process.Refresh();$log=Read-LogText $unityLog
        if($log-match'No valid Unity Editor license found|License is not active \(com\.unity\.editor\.headless\)'){throw 'Terminal Unity entitlement/license error before serial assignment.'}
        if($log-match'Serial number assigned to'){$licenseAdmitted=$true;$licenseAdmittedAt=[DateTimeOffset]::Now;Write-CreateNewJson $admissionPath ([ordered]@{schemaVersion=1;admissionKind='gate13r-48h-three-lane-license-admission-v1';executionDesignId='gate13r-48h-10pct-three-isolated-editor-lanes-serial-license-admission-v1';waveId=$WaveId;lane=$LaneNumber;processId=$process.Id;processStartTime=$started.ToString('o');admittedAt=$licenseAdmittedAt.ToString('o');admissionSeconds=($licenseAdmittedAt-$started).TotalSeconds;serialAssignmentPatternFound=$true;terminalLicensePatternFound=$false;barrierTokenSha256=Get-StringHash $BarrierToken;formalCampaign=$false});break}
        if($process.HasExited){throw 'Unity exited before serial-number assignment evidence.'};if((Get-Date)-ge$admissionDeadline){throw "License admission timed out after $LicenseAdmissionTimeoutSeconds seconds."};Start-Sleep -Milliseconds 100
    }
    if($SelfRelease){$readyDeadline=(Get-Date).AddSeconds($BarrierTimeoutSeconds);while(-not(Test-Path -LiteralPath $methodReadyPath)){if($process.HasExited){throw 'Unity exited before method-ready.'};if((Get-Date)-ge$readyDeadline){throw 'Method-ready timed out in self-release mode.'};Start-Sleep -Milliseconds 50;$process.Refresh()};Write-CreateNewJson $releasePath ([ordered]@{schemaVersion=1;releaseKind='gate13r-48h-three-lane-wave-release-v1';executionDesignId='gate13r-48h-10pct-three-isolated-editor-lanes-serial-license-admission-v1';waveId=$WaveId;barrierToken=$BarrierToken;laneCount=3;releasedAtUtc=[DateTime]::UtcNow.ToString('o');formalCampaign=$false})}
    $deadline=(Get-Date).AddSeconds($TimeoutSeconds);while(-not$process.HasExited){if((Get-Date)-ge$deadline){$timedOut=$true;break};Start-Sleep -Milliseconds 250;$process.Refresh()};if($timedOut){&taskkill.exe /PID $process.Id /T /F 2>&1|Out-Null;try{Wait-Process -Id $process.Id -Timeout 30 -ErrorAction SilentlyContinue}catch{}};$process.Refresh();$exitCode=if($timedOut){124}else{[int]$process.ExitCode}
}catch{$errors.Add($_.Exception.ToString());if($null-ne$process-and-not$process.HasExited){&taskkill.exe /PID $process.Id /T /F 2>&1|Out-Null;try{Wait-Process -Id $process.Id -Timeout 30 -ErrorAction SilentlyContinue}catch{}}}

$completed=[DateTimeOffset]::Now;$lockPath=Join-Path $LaneProjectPath 'Temp\UnityLockfile';$quiescenceDeadline=(Get-Date).AddSeconds(60);do{$laneProcesses=@(Get-LaneUnityProcesses $LaneProjectPath);$lockExists=Test-Path -LiteralPath $lockPath;if(-not$laneProcesses.Count-and-not$lockExists){break};Start-Sleep -Milliseconds 250}while((Get-Date)-lt$quiescenceDeadline);$laneProcesses=@(Get-LaneUnityProcesses $LaneProjectPath);$lockExists=Test-Path -LiteralPath $lockPath
if($timedOut){$errors.Add("Hard timeout after $TimeoutSeconds seconds.")};if($laneProcesses.Count){$errors.Add('Lane-owned Unity process remains after exit.')};if($lockExists){$errors.Add('Lane Unity lock remains after quiescence.')};if(-not$licenseAdmitted){$errors.Add('Serial-number license admission evidence is missing.')}
$compiler=@();if(Test-Path -LiteralPath $unityLog){$compiler=@(Select-String -LiteralPath $unityLog -Pattern 'error CS\d+|Compilation failed|Scripts have compiler errors|executeMethod.+could not be found' -CaseSensitive:$false)};if($compiler.Count){$errors.Add("Compiler/execute-method patterns: $($compiler.Count).")}
$manifestPath=Join-Path $OutputDirectory 'block-manifest.json';$checkpointPath=Join-Path $OutputDirectory 'block-checkpoint.json';$blockFailurePath=Join-Path $OutputDirectory 'block-failure.json';$manifest=if(Test-Path $manifestPath){Read-Json $manifestPath}else{$null};$checkpoint=if(Test-Path $checkpointPath){Read-Json $checkpointPath}else{$null};$ready=if(Test-Path $methodReadyPath){Read-Json $methodReadyPath}else{$null};$observed=if(Test-Path $barrierObservedPath){Read-Json $barrierObservedPath}else{$null}
if($null-eq$ready-or[string]$ready.waveId-ne$WaveId-or[string]$ready.barrierTokenSha256-ne(Get-StringHash $BarrierToken)-or$ready.planningWorkloadStarted-ne$false){$errors.Add('Method-ready identity/boundary missing or invalid.')};if($null-eq$observed-or[string]$observed.waveId-ne$WaveId-or$observed.planningWorkloadStartedAfterRelease-ne$true){$errors.Add('Barrier-observed record missing or invalid.')}
if($ExpectFailure){if($exitCode-eq0){$errors.Add('Negative fixture exited zero.')};if($null-ne$manifest){$errors.Add('Negative fixture wrote a completed manifest.')};if(-not(Test-Path $blockFailurePath)){$errors.Add('Negative block-failure.json missing.')};if($null-eq$checkpoint-or[string]$checkpoint.status-ne'failed-no-auto-retry'-or[int]$checkpoint.completedSampleCount-ne$ExpectedCompletedSamplesBeforeFailure){$errors.Add('Negative terminal checkpoint/count mismatch.')}}else{if($exitCode-ne0){$errors.Add("Unity exit code $exitCode.")};if($null-eq$manifest){$errors.Add('Block manifest missing.')}else{$expectedCount=@($plan.entries).Count;$expectedManaged=[long]134217728*$expectedCount;if([int]$manifest.schemaVersion-ne3-or[string]$manifest.manifestKind-ne'gate13r-48h-10pct-three-lane-nonformal-block-manifest-v1'-or[string]$manifest.executionDesignId-ne'gate13r-48h-10pct-three-isolated-editor-lanes-serial-license-admission-v1'){$errors.Add('Block manifest identity mismatch.')};if($manifest.completed-ne$true-or$manifest.formalCampaign-ne$false-or$manifest.hardMemoryRulesPassed-ne$true-or[int]$manifest.completedSampleCount-ne$expectedCount){$errors.Add('Block cardinality/boundary/memory invalid.')};if([long]$manifest.maximumManagedGrowthBytes-ne$expectedManaged-or[long]$manifest.blockRetainedManagedGrowthBytes-gt$expectedManaged-or[long]$manifest.blockWorkingSetGrowthBytes-gt536870912-or[long]$manifest.blockPrivateMemoryGrowthBytes-gt536870912){$errors.Add('Frozen memory rule failed.')}};if($null-eq$checkpoint-or[string]$checkpoint.status-ne'block-completed'){$errors.Add('Terminal block checkpoint missing/wrong.')};if(Test-Path $blockFailurePath){$errors.Add('Unexpected block failure record exists.')}}
$passed=$errors.Count-eq0;$release=if(Test-Path $releasePath){Read-Json $releasePath}else{$null};$summary=[ordered]@{schemaVersion=1;summaryKind='gate13r-48h-three-lane-block-wrapper-summary-v1';completedAtUtc=[DateTime]::UtcNow.ToString('o');mode=$Mode;waveId=$WaveId;lane=$LaneNumber;laneProjectPath=$LaneProjectPath;affinityMaskRequested=$AffinityMaskHex;affinityMaskObserved=$actualMask;blockPlanPath=$BlockPlanPath;blockPlanSha256=$planSha;blockId=[string]$plan.blockId;campaignId=[string]$plan.campaignId;block=[int]$plan.block;analysisRole=[string]$plan.analysisRole;processId=if($null-ne$process){$process.Id}else{$null};startedAt=$started.ToString('o');licenseAdmittedAt=if($null-ne$licenseAdmittedAt){$licenseAdmittedAt.ToString('o')}else{$null};methodReadyAt=if($null-ne$ready){[string]$ready.writtenAtUtc}else{$null};barrierReleasedAt=if($null-ne$release){[string]$release.releasedAtUtc}else{$null};barrierObservedAt=if($null-ne$observed){[string]$observed.observedAtUtc}else{$null};completedAt=$completed.ToString('o');licenseAdmissionSeconds=if($null-ne$licenseAdmittedAt){($licenseAdmittedAt-$started).TotalSeconds}else{$null};barrierWaitSeconds=if($null-ne$observed){[double]$observed.waitMilliseconds/1000.0}else{$null};wrapperWallSeconds=($completed-$started).TotalSeconds;unityExitCode=$exitCode;timedOut=$timedOut;licenseAdmitted=$licenseAdmitted;laneLockAbsent=-not$lockExists;laneProcessCountAfter=$laneProcesses.Count;formalCampaign=$false;automaticRetryAttempted=$false;automaticResumeAttempted=$false;errors=$errors.ToArray();passed=$passed};Write-AtomicJson $summaryPath $summary
if(-not$passed){Write-AtomicJson $failureSidecar ([ordered]@{schemaVersion=1;failureKind='gate13r-48h-three-lane-block-wrapper-failure-v1';failedAtUtc=[DateTime]::UtcNow.ToString('o');waveId=$WaveId;lane=$LaneNumber;blockId=[string]$plan.blockId;errors=$errors.ToArray();automaticRetryAttempted=$false;automaticResumeAttempted=$false;formalCampaign=$false});Write-Error("Gate13R 48h block wrapper failed: "+($errors-join'; '));exit 1}
Write-Host("Gate13R 48h block passed: lane {0}, {1}, {2:n2}s"-f$LaneNumber,$plan.blockId,($completed-$started).TotalSeconds)-ForegroundColor Green;exit 0
